(()=>{'use strict';const root=document.documentElement,gate=document.getElementById('opening'),main=document.getElementById('invitation'),openButton=document.getElementById('open-invitation');let opened=false,effects=true;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const showInvitation=()=>{if(gate.classList.contains('is-opening'))return;gate.classList.add('is-opening');openButton.disabled=true;setTimeout(()=>{gate.classList.add('is-hidden');main.inert=false;document.body.classList.remove('locked');opened=true;window.scrollTo(0,0);main.setAttribute('tabindex','-1');main.focus({preventScroll:true});document.dispatchEvent(new Event('invitation-opened'))},reduced?0:520)};openButton.addEventListener('click',showInvitation);document.querySelector('.reopen-button').addEventListener('click',()=>{opened=false;gate.classList.remove('is-opening','is-hidden');openButton.disabled=false;main.inert=true;document.body.classList.add('locked');openButton.focus()});
const hearts=document.getElementById('hearts');const addHeart=(seed=false)=>{if(!effects||reduced||document.hidden||hearts.childElementCount>20)return;const el=document.createElement('span');el.className='ambient-heart';el.textContent='♥';el.style.left=Math.random()*100+'%';el.style.setProperty('--size',7+Math.random()*7+'px');const duration=10+Math.random()*7;el.style.setProperty('--duration',duration+'s');el.style.setProperty('--drift',-25+Math.random()*50+'px');if(seed)el.style.animationDelay=-Math.random()*duration+'s';hearts.appendChild(el);setTimeout(()=>el.remove(),18000)};for(let i=0;i<12;i++)addHeart(true);setInterval(addHeart,1300);document.querySelector('.effects-toggle').addEventListener('click',e=>{effects=!effects;root.classList.toggle('effects-off',!effects);e.currentTarget.setAttribute('aria-pressed',String(effects));e.currentTarget.setAttribute('aria-label',effects?'Tắt hiệu ứng tim rơi':'Bật hiệu ứng tim rơi');if(!effects)hearts.replaceChildren();else for(let i=0;i<12;i++)addHeart(true)});
const reveals=[...document.querySelectorAll('.reveal')];if('IntersectionObserver'in window){root.classList.add('motion');const observer=new IntersectionObserver(changes=>changes.forEach(item=>{if(opened&&item.isIntersecting){item.target.classList.add('visible');observer.unobserve(item.target)}}),{threshold:.07});const watch=()=>reveals.filter(el=>!el.classList.contains('visible')).forEach(el=>{observer.unobserve(el);observer.observe(el)});document.addEventListener('invitation-opened',watch);watch()}
const dateElement=document.querySelector('main [data-card-field="weddingDate"]'),timeElement=document.querySelector('[data-card-field="weddingTime"]');let target=NaN;const updateWeddingDate=()=>{const raw=root.dataset.weddingDate||dateElement.textContent;const nums=raw.match(/\d+/g)?.map(Number)||[];if(nums.length<3)return;const [year,month,day]=nums[0]>1000?nums:[nums[2],nums[1],nums[0]];const clock=(timeElement?.textContent||'11:00').match(/(\d{1,2}):(\d{2})/);target=Date.parse(`${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}T${clock?clock[1].padStart(2,'0')+':'+clock[2]:'11:00'}:00+07:00`);document.getElementById('wedding-day').textContent=String(day).padStart(2,'0');document.getElementById('wedding-month').textContent=`THÁNG ${String(month).padStart(2,'0')} · ${year}`;const weekdays=['CHỦ NHẬT','THỨ HAI','THỨ BA','THỨ TƯ','THỨ NĂM','THỨ SÁU','THỨ BẢY'];document.getElementById('wedding-weekday').textContent=weekdays[new Date(Date.UTC(year,month-1,day)).getUTCDay()];tick()};const tick=()=>{let remaining=Number.isFinite(target)?Math.max(0,target-Date.now()):0;[86400000,3600000,60000,1000].forEach((unit,i)=>{document.getElementById(['days','hours','minutes','seconds'][i]).textContent=String(Math.floor(remaining/unit)).padStart(2,'0');remaining%=unit});const note=document.querySelector('.countdown-note');note.hidden=!Number.isFinite(target)||target>Date.now();note.textContent='Ngày vui đã đến. Cảm ơn bạn đã ở đây cùng chúng mình.'};updateWeddingDate();setInterval(tick,1000);new MutationObserver(updateWeddingDate).observe(dateElement,{childList:true,characterData:true,subtree:true});if(timeElement)new MutationObserver(updateWeddingDate).observe(timeElement,{childList:true,characterData:true,subtree:true});new MutationObserver(updateWeddingDate).observe(root,{attributes:true,attributeFilter:['data-wedding-date']});document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});
const gallery=document.getElementById('gallery'),photos=[...document.querySelectorAll('.album-photo img')];let current=0;const showPhoto=index=>{current=(index+photos.length)%photos.length;gallery.querySelector('img').src=photos[current].src;gallery.querySelector('img').alt=photos[current].alt;gallery.querySelector('.gallery-count').textContent=`${current+1} / ${photos.length}`};photos.forEach((img,index)=>img.closest('button').addEventListener('click',()=>{showPhoto(index);gallery.showModal()}));gallery.querySelector('.gallery-close').onclick=()=>gallery.close();gallery.querySelector('.gallery-prev').onclick=()=>showPhoto(current-1);gallery.querySelector('.gallery-next').onclick=()=>showPhoto(current+1);gallery.addEventListener('click',e=>{if(e.target===gallery)gallery.close()});gallery.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();showPhoto(current-1)}if(e.key==='ArrowRight'){e.preventDefault();showPhoto(current+1)}});let startX=0;gallery.addEventListener('touchstart',e=>{startX=e.changedTouches[0].clientX},{passive:true});gallery.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-startX;if(Math.abs(dx)>45)showPhoto(current+(dx<0?1:-1))},{passive:true});
const form=document.getElementById('rsvp-form'),status=form.querySelector('.form-status');form.addEventListener('submit',async e=>{e.preventDefault();if(form.dataset.busy||!form.reportValidity())return;const data=new FormData(form),name=String(data.get('name')||'').trim();if(!name){status.textContent='Bạn vui lòng nhập họ tên nhé.';return}const slug=root.dataset.cardSlug;if(!slug){status.textContent='Đây là bản xem mẫu. Bạn có thể gửi xác nhận qua đường dẫn thiệp đã xuất bản.';return}form.dataset.busy='true';const submit=form.querySelector('button[type="submit"]');submit.disabled=true;status.textContent='Đang gửi xác nhận…';try{const response=await fetch(`/api/cards/view/${encodeURIComponent(slug)}/rsvp`,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({name,attendance:data.get('attendance'),guest_count:Number(data.get('guest_count')),message:String(data.get('message')||'').trim()})});const result=await response.json();if(!response.ok||!result.success)throw Error(result.message||'Chưa gửi được xác nhận. Bạn thử lại nhé.');status.textContent=result.message||'Cảm ơn bạn. Hẹn gặp bạn trong ngày vui!';form.reset()}catch(error){status.textContent=error.message}finally{delete form.dataset.busy;submit.disabled=false}});
})();
